import{DEFAULTS,SPECS,clean,units,eventTime,simulate,PRESETS}from'./engine.js';
const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
let config={...DEFAULTS},result,baseline=null,pending=0,toastTimer=0;
const labels={kp:'比例增益 Kp',ti:'积分时间 Ti',td:'微分时间 Td',gain:'对象增益 K',tau:'时间常数 τ₁',tau2:'时间常数 τ₂',delay:'纯迟延 θ',target:'目标值',disturbance:'负荷扰动',duration:'观察时长',band:'允许误差带 ±',noise:'测量噪声幅值',filter:'微分滤波时间',umin:'输出下限',umax:'输出上限'};
const fields={};const colors={sp:'#b96b26',pv:'#1670a6',mv:'#a2b8c6',baseline:'#708187',u:'#258674',actual:'#805cab',p:'#1670a6',i:'#258674',d:'#805cab'};
function paramUnit(key){if(['ti','td','tau','tau2','delay','duration','filter'].includes(key))return'分钟';if(['umin','umax'].includes(key))return'%';if(key==='kp')return'百分点/'+units(config);if(key==='gain')return config.model==='integrating'?'%/(百分点·分)':'℃/百分点';if(key==='disturbance'&&config.model==='integrating')return'%/分钟';return units(config);}
function makeParam(key,container){const [min,max,step]=SPECS[key],div=document.createElement('div');div.className='parameter';div.dataset.key=key;
 const top=document.createElement('div');top.className='param-top';const label=document.createElement('label');label.htmlFor='range-'+key;label.textContent=labels[key];const box=document.createElement('div');box.className='param-number';const number=document.createElement('input');Object.assign(number,{type:'number',min,max,step,value:config[key]});number.setAttribute('aria-label',labels[key]+'数值');const unit=document.createElement('span');box.append(number,unit);top.append(label,box);const range=document.createElement('input');Object.assign(range,{type:'range',id:'range-'+key,min,max,step,value:config[key]});range.setAttribute('aria-label',labels[key]);div.append(top,range);$(container).append(div);fields[key]={div,number,range,unit};
 range.addEventListener('input',()=>{config[key]=+range.value;number.value=range.value;custom();schedule();});number.addEventListener('input',()=>{const value=+number.value;if(number.value!==''&&Number.isFinite(value)&&value>=min&&value<=max){config[key]=value;range.value=value;custom();schedule();}});number.addEventListener('change',()=>{if(number.value===''||!Number.isFinite(+number.value)){number.value=config[key];return;}config=clean({...config,[key]:+number.value});custom();sync();schedule();});}
['kp','ti','td'].forEach(k=>makeParam(k,'pid-controls'));['gain','tau','tau2','delay'].forEach(k=>makeParam(k,'model-controls'));['target','disturbance','duration','band'].forEach(k=>makeParam(k,'scenario-controls'));['noise','filter','umin','umax'].forEach(k=>makeParam(k,'advanced-controls'));
function sync(){for(const[k,f]of Object.entries(fields)){f.range.value=config[k];f.number.value=config[k];f.unit.textContent=paramUnit(k);const disabled=(k==='ti'&&!config.enableI)||(k==='td'&&!config.enableD);f.range.disabled=disabled;f.number.disabled=disabled;f.div.hidden=(k==='tau'&&config.model==='integrating')||(k==='tau2'&&config.model!=='sopdt')||(k==='disturbance'&&config.scenario==='step');}
 $('enable-i').checked=config.enableI;$('enable-d').checked=config.enableD;$('anti-windup').checked=config.antiWindup;$('model').value=config.model;$('scenario').value=config.scenario;
 $('response-title').textContent=config.model==='integrating'?'液位响应':'温度响应';$('model-tag').textContent={sopdt:'SOPDT / TWO LAGS',fopdt:'FOPDT / ONE LAG',integrating:'INTEGRATING / LEVEL'}[config.model];
 $('equation').textContent=config.model==='integrating'?`dy/dt = ${config.gain} × (u延迟 − 40) + 负荷扰动；θ=${config.delay} min`:`τ₁=${config.tau} min${config.model==='sopdt'?'；τ₂='+config.tau2+' min':''}；K=${config.gain} ℃/百分点；θ=${config.delay} min`;
 $('measured-key').hidden=config.noise===0;$('baseline-key').hidden=!baseline;$('compare-panel').hidden=!baseline;
}
function custom(){document.querySelectorAll('[data-preset]').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false');});$('experiment-note').textContent='自定义实验 · 拖动后从同一初始状态重新计算；所有时间单位为分钟。';}
document.querySelectorAll('[data-preset]').forEach(b=>b.addEventListener('click',()=>{config=clean({...DEFAULTS,...PRESETS[b.dataset.preset].values});if(baseline&&units(config)!==units(baseline.config))baseline=null;document.querySelectorAll('[data-preset]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});$('experiment-note').textContent=PRESETS[b.dataset.preset].note;sync();schedule();}));
for(const[id,key]of[['enable-i','enableI'],['enable-d','enableD'],['anti-windup','antiWindup']])$(id).addEventListener('change',()=>{config[key]=$(id).checked;custom();sync();schedule();});
for(const key of['scenario','model'])$(key).addEventListener('change',()=>{config[key]=$(key).value;if(baseline&&units(config)!==units(baseline.config)){baseline=null;notify('对象单位已改变，已清除原对比');}if(key==='model'){if(config.model==='integrating'){config.gain=0.12;config.disturbance=-0.5;config.kp=2;config.ti=6;}else{config.gain=0.8;config.disturbance=-8;config.kp=2;config.ti=3;}}custom();sync();schedule();});
$('reset').addEventListener('click',()=>{config={...DEFAULTS};if(baseline&&units(config)!==units(baseline.config))baseline=null;$('experiment-note').textContent=PRESETS.pi.note;document.querySelectorAll('[data-preset]').forEach(b=>{b.classList.toggle('selected',b.dataset.preset==='pi');b.setAttribute('aria-pressed',String(b.dataset.preset==='pi'));});sync();schedule();});
$('save-baseline').addEventListener('click',()=>{baseline={config:{...config},result:structuredClone(result)};sync();render();notify('已保存当前参数和响应，继续拖动即可对比');});
$('clear-baseline').addEventListener('click',()=>{baseline=null;sync();render();});
$('share').addEventListener('click',async()=>{const encoded=encodeURIComponent(JSON.stringify(config)),url=new URL(location.href);url.hash='v1='+encoded;history.replaceState(null,'',url);try{await navigator.clipboard.writeText(url.href);notify('已复制链接，打开后恢复这组参数');}catch{notify('参数已写入地址栏，可复制当前网址分享');}});
function notify(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function schedule(){cancelAnimationFrame(pending);pending=requestAnimationFrame(()=>{const start=performance.now();result=simulate(config);render();$('calculation').textContent=`${result.rows.length.toLocaleString()} 步 · Δt ${result.dt.toFixed(3)} min · ${(performance.now()-start).toFixed(0)} ms`;try{localStorage.setItem('pid-lab-v1',JSON.stringify(config));}catch{}});}
function fmt(n,d=2){return Number.isFinite(n)?(Math.abs(n)<0.5*10**(-d)?0:n).toFixed(d):'—';}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function metricEntries(r){const m=r.metrics,c=r.config,u=units(c);return[
 ['最大'+(c.scenario==='step'?'超调':'偏离'),fmt(c.scenario==='step'?m.overshoot:m.maxDeviation),u,c.scenario==='step'?'相对目标、沿阶跃方向':'事件后的最大绝对偏离'],
 ['调节时间',m.settled===null?'未确认':fmt(m.settled,1),'min',`±${c.band}${u} 带内，末段≥3 min`],
 ['窗口末偏差',fmt(m.error),u,`目标 − 真实值，t=${fmt(m.lastTime,0)} min`],
 ['IAE',fmt(m.iae),u+'·min','绝对误差积分'],['ITAE',fmt(m.itae),u+'·min²','按事件后时间加权'],['输出限幅时间',fmt(m.saturation,1),'min','控制需求超过输出限制']];}
function render(){const m=result.metrics;$('status').textContent=m.stopped?'模型越界，计算已停止':m.settled===null?'观察时段内尚未确认进入稳定误差带':'已在观察窗口内进入并保持允许误差带';$('status').className=m.stopped?'warning':'';
 $('metrics').innerHTML=metricEntries(result).map(([label,value,unit,foot])=>`<div><div class="metric-label">${esc(label)}</div><div class="metric-value">${esc(value)}<small>${value==='未确认'?'':esc(unit)}</small></div><div class="metric-foot">${esc(foot)}</div></div>`).join('');
 const different=baseline&&Object.keys(config).some(k=>!['kp','ti','td','enableI','enableD','filter','antiWindup'].includes(k)&&config[k]!==baseline.config[k]);$('compare-note').hidden=!different;$('compare-note').textContent='对比条件不同：对象、输入、噪声或评价设置已改变。曲线可观察，指标不作同工况优劣比较。';
 if(baseline){const current=metricEntries(result),old=metricEntries(baseline.result);const head=[['控制形式',config.enableD?(config.enableI?'PID':'PD'):(config.enableI?'PI':'P'),baseline.config.enableD?(baseline.config.enableI?'PID':'PD'):(baseline.config.enableI?'PI':'P')],['Kp / Ti / Td',[config.kp,config.enableI?config.ti:'关闭',config.enableD?config.td:'关闭'].join(' / '),[baseline.config.kp,baseline.config.enableI?baseline.config.ti:'关闭',baseline.config.enableD?baseline.config.td:'关闭'].join(' / ')]];$('compare-body').innerHTML=[...head,...current.map((e,i)=>[e[0],e[1]+' '+e[2],old[i][1]+' '+old[i][2]])].map(row=>'<tr>'+row.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('');}
 drawAll();}
function svgEl(tag,attrs={},text){const e=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));if(text!==undefined)e.textContent=text;return e;}
function drawAll(){if(!result)return;const unit=units(config);const process=[{key:'sp',label:'目标',dash:'6 4'},...(config.noise?[{key:'mv',label:'测量',width:1,opacity:.6}]:[]),{key:'pv',label:'真实值'}];if(baseline)process.push({key:'pv',label:'对比',id:'baseline',rows:baseline.result.rows,dash:'5 4'});chart('process-chart',320,process,unit);chart('output-chart',190,[{key:'u',label:'指令'},{key:'actual',label:'实际作用量',dash:'4 3'}],'%',[config.umin,config.umax]);if(document.querySelector('.contributions').open)chart('terms-chart',210,[{key:'p',label:'P'},{key:'i',label:'I'},{key:'d',label:'D',dash:'4 3'}],'百分点');}
function niceStep(raw){const base=10**Math.floor(Math.log10(Math.max(1e-9,raw))),m=raw/base;return(m<=1?1:m<=2?2:m<=5?5:10)*base;}
function chart(id,height,lines,yUnit,refs=[]){const holder=$(id),w=Math.max(260,holder.clientWidth),m={left:55,right:14,top:27,bottom:38},pw=w-m.left-m.right,ph=height-m.top-m.bottom;let lo=Infinity,hi=-Infinity;for(const l of lines)for(const r of(l.rows||result.rows)){lo=Math.min(lo,r[l.key]);hi=Math.max(hi,r[l.key]);}for(const v of refs){lo=Math.min(lo,v);hi=Math.max(hi,v);}if(!Number.isFinite(lo)||!Number.isFinite(hi))return;const pad=Math.max((hi-lo)*.1,yUnit==='%'?2:.5);lo-=pad;hi+=pad;const step=niceStep((hi-lo)/4);lo=Math.floor(lo/step)*step;hi=Math.ceil(hi/step)*step;const xmax=Math.max(result.rows.at(-1).t,baseline&&id==='process-chart'?baseline.result.rows.at(-1).t:0);const x=v=>m.left+pw*v/xmax,y=v=>m.top+ph*(hi-v)/(hi-lo);
 const svg=svgEl('svg',{viewBox:`0 0 ${w} ${height}`,role:'img','aria-label':holder.getAttribute('aria-label')});svg.append(svgEl('title',{},holder.getAttribute('aria-label')));const defs=svgEl('defs'),clip=svgEl('clipPath',{id:id+'-clip'});clip.append(svgEl('rect',{x:m.left,y:m.top,width:pw,height:ph}));defs.append(clip);svg.append(defs);svg.append(svgEl('rect',{x:m.left,y:m.top,width:pw,height:ph,fill:'none',stroke:'#d9e1e1'}));
 for(let v=lo;v<=hi+step*.1;v+=step){svg.append(svgEl('line',{x1:m.left,x2:w-m.right,y1:y(v),y2:y(v),stroke:'#e8eded','stroke-width':1}));svg.append(svgEl('text',{x:m.left-8,y:y(v)+4,'text-anchor':'end'},fmt(v,step<1?1:0)));}
 const ticks=w<450?3:6;for(let j=0;j<=ticks;j++){const t=xmax*j/ticks;svg.append(svgEl('text',{x:x(t),y:height-20,'text-anchor':j===0?'start':j===ticks?'end':'middle'},fmt(t,0)));}svg.append(svgEl('text',{x:m.left,y:15},yUnit));svg.append(svgEl('text',{x:m.left+pw/2,y:height-3,'text-anchor':'middle'},'时间 / min'));
 const event=result.event;if(event<xmax){svg.append(svgEl('line',{x1:x(event),x2:x(event),y1:m.top,y2:m.top+ph,stroke:'#bac7cc','stroke-dasharray':'2 4'}));}
 const g=svgEl('g',{'clip-path':`url(#${id}-clip)`});if(id==='process-chart'){g.append(svgEl('rect',{x:x(result.event),y:y(config.target+config.band),width:Math.max(0,w-m.right-x(result.event)),height:y(config.target-config.band)-y(config.target+config.band),fill:'#258674',opacity:0.065}));}
 for(const line of lines){const rows=line.rows||result.rows,stride=Math.max(1,Math.floor(rows.length/1600)),sample=rows.filter((r,i)=>i%stride===0||i===rows.length-1);const d=sample.map((r,i)=>(i?'L':'M')+fmt(x(r.t),2)+','+fmt(y(r[line.key]),2)).join(' ');g.append(svgEl('path',{d,fill:'none',stroke:colors[line.id||line.key],'stroke-width':line.width||1.8,'stroke-dasharray':line.dash||'',opacity:line.opacity||1}));}svg.append(g);
 const guide=svgEl('line',{y1:m.top,y2:m.top+ph,stroke:'#82969f','stroke-width':1,visibility:'hidden'});svg.append(guide);const markers=lines.map(l=>{const c=svgEl('circle',{r:3,fill:colors[l.id||l.key],visibility:'hidden'});svg.append(c);return c;});const overlay=svgEl('rect',{x:m.left,y:m.top,width:pw,height:ph,fill:'transparent'});svg.append(overlay);const tip=document.createElement('div');tip.className='plot-tooltip';tip.hidden=true;holder.replaceChildren(svg,tip);
 function show(ev){const rect=svg.getBoundingClientRect(),px=Math.max(m.left,Math.min(w-m.right,(ev.clientX-rect.left)*w/rect.width)),t=(px-m.left)/pw*xmax;guide.setAttribute('x1',px);guide.setAttribute('x2',px);guide.setAttribute('visibility','visible');const text=[fmt(t,2)+' min'];lines.forEach((l,i)=>{const rows=l.rows||result.rows;if(t>rows.at(-1).t){markers[i].setAttribute('visibility','hidden');return;}let a=0,b=rows.length-1;while(a<b){const mid=(a+b)>>1;if(rows[mid].t<t)a=mid+1;else b=mid;}const r=rows[a],p=rows[Math.max(0,a-1)],f=r.t===p.t?0:(t-p.t)/(r.t-p.t),v=p[l.key]+f*(r[l.key]-p[l.key]);markers[i].setAttribute('cx',px);markers[i].setAttribute('cy',y(v));markers[i].setAttribute('visibility','visible');text.push(l.label+' '+fmt(v,2)+' '+yUnit);});tip.textContent=text.join('\n');tip.hidden=false;tip.style.left=Math.max(0,Math.min(holder.clientWidth-tip.offsetWidth,px+12))+'px';tip.style.top='25px';}
 overlay.addEventListener('pointermove',show);overlay.addEventListener('pointerdown',show);overlay.addEventListener('pointerleave',e=>{if(e.pointerType!=='touch'){tip.hidden=true;guide.setAttribute('visibility','hidden');markers.forEach(c=>c.setAttribute('visibility','hidden'));}});
}
$('csv').addEventListener('click',()=>{const lines=['# PID Lab configuration: '+JSON.stringify(config),'# SP/PV unit: '+units(config)+'; time: min; P/I/D: output percentage points','time_min,SP,PV_true,PV_measured,command_pct,actual_pct,P_pp,I_pp,D_pp,raw_output_pct,load'];for(const r of result.rows)lines.push([r.t,r.sp,r.pv,r.mv,r.u,r.actual,r.p,r.i,r.d,r.raw,r.load].map(v=>Number(v).toPrecision(9)).join(','));const blob=new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='pid-lab-response.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('已导出配置与本次完整响应数据');});
document.querySelector('.contributions').addEventListener('toggle',drawAll);let lastWidth=0;new ResizeObserver(e=>{const w=e[0].contentRect.width;if(Math.abs(w-lastWidth)>1){lastWidth=w;drawAll();}}).observe(document.querySelector('.results'));
try{if(location.hash.startsWith('#v1='))config=clean(JSON.parse(decodeURIComponent(location.hash.slice(4))));else{const stored=localStorage.getItem('pid-lab-v1');if(stored)config=clean(JSON.parse(stored));}}catch{notify('参数链接无效，已采用默认值');}
custom();sync();result=simulate(config);render();$('calculation').textContent=`${result.rows.length.toLocaleString()} 步 · Δt ${result.dt.toFixed(3)} min`;
